  // 查食物三宏量（g / 100g）；未知食物返回估算
  getNutri(name, gram) {
    const m = this.nutriMap[name];
    if (m) {
      return {
        p: Math.round((m[0] * gram / 100) * 10) / 10,
        c: Math.round((m[1] * gram / 100) * 10) / 10,
        f: Math.round((m[2] * gram / 100) * 10) / 10,
      };
    }
    // 估算：未匹配按 9% 蛋白/45% 碳水/15% 脂肪（普通餐食均值）
    return {
      p: Math.round(gram * 0.09 * 10) / 10,
      c: Math.round(gram * 0.45 * 10) / 10,
      f: Math.round(gram * 0.15 * 10) / 10,
      est: true,
    };
  },

