    // 专升本计算机考点池（每日推送10条）
    memoryCS: [
      { k:'冯·诺依曼体系', d:'五大部件：运算器、控制器、存储器、输入、输出设备；核心是存储程序原理，数据和指令用二进制存储在内存中。' },
      { k:'计算机四代', d:'第一代(1946-57)电子管；第二代(58-64)晶体管；第三代(65-70)中小规模集成电路；第四代(71-)超大规模集成电路。' },
      { k:'CPU组成', d:'运算器ALU+控制器CU；运算器负责算术/逻辑运算，控制器负责取指、译码、发出时序控制信号。' },
      { k:'存储器层次', d:'速度递减/容量递增：CPU寄存器→Cache(SRAM)→主存(DRAM)→SSD→HDD；局部性原理是缓存基础。' },
      { k:'单位换算', d:'1B=8bit；1KB=1024B；1MB=1024KB；1GB=1024MB；1TB=1024GB。注意硬盘厂用十进制1000。' },
      { k:'进制转换', d:'十进制→二进制：除2取余逆序；二进制→十六进制：4位一组；八进制每位=3位二进制。' },
      { k:'ASCII码', d:'标准7位=128字符；空格32，0→48，A→65，a→97；小写比对应大写ASCII大32。' },
      { k:'操作系统功能', d:'进程管理、存储管理、文件管理、设备管理、用户接口(作业管理)五大功能。' },
      { k:'进程 vs 线程', d:'进程是资源分配基本单位，有独立地址空间；线程是CPU调度基本单位，共享进程资源；进程切换开销远大于线程。' },
      { k:'进程三态', d:'就绪(等CPU)→运行(占CPU)→阻塞(等I/O)；就绪→运行是调度选中，运行→阻塞是主动等事件，运行→就绪是时间片到。' },
      { k:'死锁四条件', d:'互斥、请求与保持、不剥夺、循环等待；缺一不可，破坏任一即可预防死锁。' },
      { k:'数据库三级模式', d:'外模式(用户视图)→模式(逻辑结构)→内模式(物理存储)；二级映像保证逻辑/物理独立性。' },
      { k:'SQL增删改查', d:'SELECT选、INSERT增、UPDATE改、DELETE删；WHERE过滤、ORDER排序、GROUP分组、JOIN连接。' },
      { k:'网络七层模型', d:'OSI七层：物理→数据链路→网络(IP)→传输(TCP/UDP)→会话→表示→应用(HTTP/HTTPS/FTP)。' },
      { k:'TCP vs UDP', d:'TCP面向连接、可靠、三次握手、流量控制；UDP无连接、不可靠、速度快、适合直播/游戏。' },
      { k:'HTTP vs HTTPS', d:'HTTP明文80端口；HTTPS=TLS加密+HTTP443端口；对称加密传数据，非对称加密协商会话密钥。' },
      { k:'数据结构复杂度', d:'数组随机访问O(1)插入删除O(n)；链表插入删除O(1)访问O(n)；哈希表平均O(1)最坏O(n)。' },
      { k:'排序复杂度', d:'冒泡/选择/插入O(n²)原地稳定；快排平均O(nlogn)原地不稳定最坏O(n²)；归并O(nlogn)稳定需空间；堆排O(nlogn)原地。' },
      { k:'二叉树性质', d:'第i层最多2^(i-1)结点；深度k最多2^k-1结点；n0=n2+1（叶子=度2结点数+1）。' },
      { k:'常见算法思想', d:'分治(快排/归并/二分)、动态规划(背包/LIS/爬楼梯)、贪心(活动选择/哈夫曼)、回溯(N皇后/全排列)、BFS/DFS图遍历。' },
    ],
